<?php
namespace App\Http\Controllers\Api\Owner;use App\Http\Controllers\Controller;use App\Models\RentalCategory;use Illuminate\Http\Request;use Illuminate\Support\Str;
class RentalCategoryController extends Controller{public function index(){return RentalCategory::orderBy('sort_order')->get();}public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:120','description'=>'nullable|string','sort_order'=>'nullable|integer','is_active'=>'sometimes|boolean']);$d['slug']=Str::slug($d['name']);return response()->json(RentalCategory::create($d),201);}public function update(Request $r,RentalCategory $rental_category){$d=$r->validate(['name'=>'required|string|max:120','description'=>'nullable|string','sort_order'=>'nullable|integer','is_active'=>'sometimes|boolean']);$d['slug']=Str::slug($d['name']);$rental_category->update($d);return $rental_category;}public function destroy(RentalCategory $rental_category){abort_if($rental_category->items()->exists(),422,'Category still has items.');$rental_category->delete();return response()->noContent();}}
